window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-93440ebe05e21db0"]={"versions": [{"id": "FIG-93440ebe05e21db0", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenmodell zur Veranschaulichung der Datenkapselung und Schichtenkommunikation im AUTOSAR-Kommunikationsstack (angelehnt an OSEK/VDX Communication). Das Diagramm stellt das generische Schichtenkonzept (Layer N+1, Layer N, Layer N-1) sowie ein konkretes Instanziierungsbeispiel anhand von Transport Protocol (TP) und CAN-Treiber/Interface gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Schichten und Datenstrukturen:</p>\n<ul class=\"fig-list\"><li>Schichten (generisch): Layer N+1 (obere Schicht), Layer N (mittlere Schicht), Layer N-1 (untere Schicht).\n</li><li>Schichten (konkret): TP (Transport Protocol), CAN (Controller Area Network Layer).\n</li><li>Datenstrukturen:\n<ul class=\"fig-list\"><li>PDU (Protocol Data Unit): Aus Sicht der sendenden Schicht zusammengesetzte Dateneinheit aus Nutzdaten (<code>data structure</code>) und Protokollkontrollinformation (<code>PCI</code>).\n</li><li>SDU (Service Data Unit): Aus Sicht der empfangenden Folge- bzw. Unterschicht übergebene Nutzdateneinheit (<code>data structure</code>), die der gesamten PDU der übergeordneten Schicht entspricht.\n</li><li>PCI (Protocol Control Information): Schichtspezifische Steuer- und Adressierungsdaten.\n</li></ul>\n</li><li>Schnittstellenfunktionen (Signaturen):\n<ul class=\"fig-list\"><li><code>LayerN_Tx(*PDU);</code> (Aufruf / Übergabe von Layer N+1 an Layer N)\n</li><li><code>void LayerN_Tx(*SDU);</code> (Schnittstellensignatur am Übergang zu Layer N)\n</li><li><code>LayerN+1_Tx(*PDU);</code> (Aufruf am Übergang von Layer N zu Layer N-1)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der Sendedatenkapselung (Transmission Side):</p>\n<ol class=\"fig-list\"><li>In <code>Layer N+1</code> liegt eine Nutzdatenstruktur als <code>PDU</code> vor.\n</li><li><code>Layer N+1</code> ruft die Sendefunktion <code>LayerN_Tx(*PDU)</code> auf; an der Schichtengrenze nimmt <code>Layer N</code> diese Datenstruktur als <code>SDU</code> über die Funktionssignatur <code>void LayerN_Tx(*SDU)</code> entgegen.\n</li><li>In <code>Layer N</code> wird der empfangenen SDU eine ebenenspezifische Steuerinformation (<code>PCI</code>) vorangestellt. Die Kombination aus <code>PCI</code> und <code>data structure</code> bildet die neue <code>PDU</code> von <code>Layer N</code>.\n</li><li>Die Übergabe an <code>Layer N-1</code> erfolgt analog über den Aufruf <code>LayerN+1_Tx(*PDU)</code>.\n</li><li>Im konkreten Beispiel (TP zu CAN) wird die vollständige PDU der TP-Ebene (bestehend aus TP-PCI und TP-SDU/Nutzdaten) beim Wechsel auf CAN zur reinen Nutzdatenstruktur (<code>data structure</code> bzw. SDU) der CAN-Schicht, der wiederum eine eigene CAN-spezifische PCI beigestellt wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient der terminologischen und konzeptionellen Definition im AUTOSAR-Glossar für PDU und SDU. Für Entwickler von BSW-Kommunikationsmodulen (z. B. PduR, CanTp, CanIf) gilt: Eine PDU einer übergeordneten Schicht wird an der Serviceschnittstelle deterministisch zur SDU der untergeordneten Schicht (<code>PDU_Layer_N = SDU_Layer_N-1</code>). Der Sendeaufruf muss die Kapselung und Zuordnung von PDU/SDU-Zeigern sowie den Pufferversatz für Protokollkontrollinformationen (PCI) strikt berücksichtigen.</p>"}, {"id": "FIG-03bd3553d1f7fb45", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenmodell zur Veranschaulichung der Datenkapselung und Schichtenkommunikation im AUTOSAR-Kommunikationsstack (angelehnt an OSEK/VDX Communication). Das Diagramm stellt das generische Schichtenkonzept (Layer N+1, Layer N, Layer N-1) sowie ein konkretes Instanziierungsbeispiel anhand von Transport Protocol (TP) und CAN-Treiber/Interface gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Schichten und Datenstrukturen:</p>\n<ul class=\"fig-list\"><li>Schichten (generisch): Layer N+1 (obere Schicht), Layer N (mittlere Schicht), Layer N-1 (untere Schicht).\n</li><li>Schichten (konkret): TP (Transport Protocol), CAN (Controller Area Network Layer).\n</li><li>Datenstrukturen:\n<ul class=\"fig-list\"><li>PDU (Protocol Data Unit): Aus Sicht der sendenden Schicht zusammengesetzte Dateneinheit aus Nutzdaten (<code>data structure</code>) und Protokollkontrollinformation (<code>PCI</code>).\n</li><li>SDU (Service Data Unit): Aus Sicht der empfangenden Folge- bzw. Unterschicht übergebene Nutzdateneinheit (<code>data structure</code>), die der gesamten PDU der übergeordneten Schicht entspricht.\n</li><li>PCI (Protocol Control Information): Schichtspezifische Steuer- und Adressierungsdaten.\n</li></ul>\n</li><li>Schnittstellenfunktionen (Signaturen):\n<ul class=\"fig-list\"><li><code>LayerN_Tx(*PDU);</code> (Aufruf / Übergabe von Layer N+1 an Layer N)\n</li><li><code>void LayerN_Tx(*SDU);</code> (Schnittstellensignatur am Übergang zu Layer N)\n</li><li><code>LayerN+1_Tx(*PDU);</code> (Aufruf am Übergang von Layer N zu Layer N-1)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der Sendedatenkapselung (Transmission Side):</p>\n<ol class=\"fig-list\"><li>In <code>Layer N+1</code> liegt eine Nutzdatenstruktur als <code>PDU</code> vor.\n</li><li><code>Layer N+1</code> ruft die Sendefunktion <code>LayerN_Tx(*PDU)</code> auf; an der Schichtengrenze nimmt <code>Layer N</code> diese Datenstruktur als <code>SDU</code> über die Funktionssignatur <code>void LayerN_Tx(*SDU)</code> entgegen.\n</li><li>In <code>Layer N</code> wird der empfangenen SDU eine ebenenspezifische Steuerinformation (<code>PCI</code>) vorangestellt. Die Kombination aus <code>PCI</code> und <code>data structure</code> bildet die neue <code>PDU</code> von <code>Layer N</code>.\n</li><li>Die Übergabe an <code>Layer N-1</code> erfolgt analog über den Aufruf <code>LayerN+1_Tx(*PDU)</code>.\n</li><li>Im konkreten Beispiel (TP zu CAN) wird die vollständige PDU der TP-Ebene (bestehend aus TP-PCI und TP-SDU/Nutzdaten) beim Wechsel auf CAN zur reinen Nutzdatenstruktur (<code>data structure</code> bzw. SDU) der CAN-Schicht, der wiederum eine eigene CAN-spezifische PCI beigestellt wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient der terminologischen und konzeptionellen Definition im AUTOSAR-Glossar für PDU und SDU. Für Entwickler von BSW-Kommunikationsmodulen (z. B. PduR, CanTp, CanIf) gilt: Eine PDU einer übergeordneten Schicht wird an der Serviceschnittstelle deterministisch zur SDU der untergeordneten Schicht (<code>PDU_Layer_N = SDU_Layer_N-1</code>). Der Sendeaufruf muss die Kapselung und Zuordnung von PDU/SDU-Zeigern sowie den Pufferversatz für Protokollkontrollinformationen (PCI) strikt berücksichtigen.</p>"}], "trans": [{"from": "FIG-93440ebe05e21db0", "to": "FIG-03bd3553d1f7fb45", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
